import json
import os
import re

def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    with open(file_path, 'r') as f:
        fileDeserializer = __import__('yaml')
        tempload = lambda t: fileDeserializer.load(t, Loader=fileDeserializer.Loader)
        data = tempload(f)

    required_fields = INPUT_JSON.get("required", [])
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Required attribute '{field}' is missing.")

    properties = INPUT_JSON.get("properties", {})
    for key, val in data.items():
        if key in properties:
            expected_type = properties[key].get("type")
            if expected_type and not isinstance(val, expected_type):
                raise ValueError(f"Attribute '{key}' type mismatch.")

    if "email" in data:
        if not re.match(EMAIL_REGEX, data["email"]):
            raise ValueError("Invalid email format.")

    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found.")

    return data[attribute]
